mapper.select:
SELECT action_job_id FROM tt_action_job
WHERE status IN ('READY', 'RETRY_WAIT')
  AND available_at <= #{now}
  AND next_attempt_at <= #{now}
  AND (expires_at IS NULL OR expires_at > #{now})
ORDER BY next_attempt_at ASC, available_at ASC, action_job_id ASC
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE tt_action_job SET
    status = 'CANCELLED',
    outcome_code = #{outcomeCode},
    completed_at = #{completedAt},
    updated_at = #{updatedAt}
WHERE instance_id = #{instanceId}
  AND definition_control_generation != #{definitionControlGeneration}
  AND status IN ('READY', 'RETRY_WAIT')

mapper.select:
SELECT * FROM tt_action_job
WHERE 1=1
AND definition_id = #{definitionId}
AND instance_id = #{instanceId}
AND status = #{status}
AND handler_key = #{handlerKey}
AND action_job_id > #{cursor}
ORDER BY action_job_id ASC
LIMIT #{limit}
